(function () {
'use strict';
function initMenu() {
var btn = document.querySelector('.menu-toggle');
var nav = document.getElementById('site-nav');
if (!btn || !nav) return;
btn.hidden = false;
function setOpen(open, returnFocus) {
nav.classList.toggle('open', open);
btn.setAttribute('aria-expanded', String(open));
if (!open && returnFocus) btn.focus();
}
btn.addEventListener('click', function () {
setOpen(btn.getAttribute('aria-expanded') !== 'true');
});
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape' && nav.classList.contains('open')) setOpen(false, true);
});
nav.addEventListener('click', function (e) {
if (e.target.closest('a')) setOpen(false);
});
if (window.matchMedia) {
window.matchMedia('(min-width:900px)').addEventListener('change', function (m) {
if (m.matches) setOpen(false);
});
}
}
function initAccordion() {
document.querySelectorAll('[data-accordion]').forEach(function (root) {
var buttons = Array.prototype.slice.call(root.querySelectorAll('.acc-btn'));
buttons.forEach(function (b, i) {
b.addEventListener('click', function () { toggle(b); });
b.addEventListener('keydown', function (e) {
var n = null;
if (e.key === 'ArrowDown') n = buttons[(i + 1) % buttons.length];
if (e.key === 'ArrowUp') n = buttons[(i - 1 + buttons.length) % buttons.length];
if (e.key === 'Home') n = buttons[0];
if (e.key === 'End') n = buttons[buttons.length - 1];
if (n) { e.preventDefault(); n.focus(); }
});
});
function toggle(b) {
var open = b.getAttribute('aria-expanded') === 'true';
b.setAttribute('aria-expanded', String(!open));
document.getElementById(b.getAttribute('aria-controls')).classList.toggle('open', !open);
}
});
}
var MAX_BYTES = 20 * 1024 * 1024;
var ALLOWED = ['jpg','jpeg','png','gif','webp','mp4','mov','webm','mp3','wav','m4a','pdf','doc','docx','txt'];
var EXPECT = { jpg:'jpeg', jpeg:'jpeg', png:'png', gif:'gif', webp:'webp', pdf:'pdf', docx:'zip', doc:'ole',
mp4:'mp4', mov:'mp4', m4a:'mp4', webm:'webm', mp3:'mp3', wav:'wav', txt:'text' };
function ext(name) { var m = /\.([a-z0-9]+)$/i.exec(name); return m ? m[1].toLowerCase() : ''; }
function fmtSize(b) { return b < 1024 ? b + ' B' : b < 1048576 ? (b / 1024).toFixed(1) + ' KB' : (b / 1048576).toFixed(2) + ' MB'; }
function kind(file, e) {
var t = file.type || '';
if (/^image/.test(t) || /^(jpg|jpeg|png|gif|webp)$/.test(e)) return 'Image';
if (/^video/.test(t) || /^(mp4|mov|webm)$/.test(e)) return 'Video';
if (/^audio/.test(t) || /^(mp3|wav|m4a)$/.test(e)) return 'Audio';
return 'Document';
}
function signature(u) {
function at(i, s) { for (var k = 0; k < s.length; k++) if (u[i + k] !== s.charCodeAt(k)) return false; return true; }
if (u[0] === 0xFF && u[1] === 0xD8 && u[2] === 0xFF) return 'jpeg';
if (u[0] === 0x89 && at(1, 'PNG')) return 'png';
if (at(0, 'GIF8')) return 'gif';
if (at(0, 'RIFF') && at(8, 'WEBP')) return 'webp';
if (at(0, 'RIFF') && at(8, 'WAVE')) return 'wav';
if (at(0, '%PDF')) return 'pdf';
if (at(0, 'PK') && u[2] === 3 && u[3] === 4) return 'zip';
if (u[0] === 0xD0 && u[1] === 0xCF && u[2] === 0x11 && u[3] === 0xE0) return 'ole';
if (at(4, 'ftyp')) return 'mp4';
if (u[0] === 0x1A && u[1] === 0x45 && u[2] === 0xDF && u[3] === 0xA3) return 'webm';
if (at(0, 'ID3') || (u[0] === 0xFF && (u[1] & 0xE0) === 0xE0)) return 'mp3';
for (var i = 0; i < u.length; i++) if (u[i] === 0) return 'binary';
return 'text';
}
function initInspector() {
var input = document.getElementById('file-input');
if (!input) return;
var $ = function (id) { return document.getElementById(id); };
var errBox = $('file-error'), results = $('results'), zone = $('dropzone');
var bInspect = $('btn-inspect'), bAnalyze = $('btn-analyze');
var file = null;
function setError(msg) { errBox.textContent = msg || ''; }
function reset() {
file = null; bInspect.disabled = bAnalyze.disabled = true; results.hidden = true;
$('m-name').textContent = 'No file selected';
['m-type', 'm-size', 'm-date'].forEach(function (id) { $(id).textContent = '—'; });
$('m-hint').hidden = false; $('file-icon').textContent = 'FILE';
}
function show(el, html) { el.innerHTML = html; el.hidden = false; }
function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
function choose(f) {
reset(); setError('');
if (!f) return;
var e = ext(f.name);
if (ALLOWED.indexOf(e) === -1) { setError('Unsupported file type ".' + e + '". Please choose an image, video, audio, PDF, DOC, DOCX or TXT file.'); input.value = ''; return; }
if (f.size > MAX_BYTES) { setError('That file is ' + fmtSize(f.size) + '. The limit is 20 MB.'); input.value = ''; return; }
if (f.size === 0) { setError('That file is empty.'); input.value = ''; return; }
file = f;
$('m-name').textContent = f.name;
$('m-type').textContent = f.type || ('.' + e);
$('m-size').textContent = fmtSize(f.size);
$('m-date').textContent = f.lastModified ? new Date(f.lastModified).toLocaleDateString() : '—';
$('m-hint').hidden = true; $('file-icon').textContent = e.toUpperCase();
bInspect.disabled = bAnalyze.disabled = false;
}
input.addEventListener('change', function () { choose(input.files[0]); });
['dragenter', 'dragover'].forEach(function (n) { zone.addEventListener(n, function (e) { e.preventDefault(); zone.classList.add('is-over'); }); });
['dragleave', 'drop'].forEach(function (n) { zone.addEventListener(n, function (e) { e.preventDefault(); zone.classList.remove('is-over'); }); });
zone.addEventListener('drop', function (e) {
var f = e.dataTransfer && e.dataTransfer.files[0];
if (f) { try { input.files = e.dataTransfer.files; } catch (x) {  } choose(f); }
});
bInspect.addEventListener('click', function () {
if (!file) return;
var k = kind(file, ext(file.name)), rows = ['<li>Category: ' + k + '</li>', '<li>Size: ' + fmtSize(file.size) + ' (' + file.size.toLocaleString() + ' bytes)</li>'];
var url = URL.createObjectURL(file);
function done(extra) { URL.revokeObjectURL(url); show(results, '<h3>File properties</h3><ul>' + rows.join('') + (extra || '') + '</ul>'); }
if (k === 'Image') {
var img = new Image();
img.onload = function () { done('<li>Dimensions: ' + img.naturalWidth + ' × ' + img.naturalHeight + ' px</li>'); };
img.onerror = function () { done('<li>Dimensions could not be read.</li>'); };
img.src = url;
} else if (k === 'Video' || k === 'Audio') {
var m = document.createElement(k === 'Video' ? 'video' : 'audio');
m.preload = 'metadata';
m.onloadedmetadata = function () { done('<li>Duration: ' + m.duration.toFixed(1) + ' s</li>' + (k === 'Video' ? '<li>Frame size: ' + m.videoWidth + ' × ' + m.videoHeight + ' px</li>' : '')); };
m.onerror = function () { done('<li>Duration could not be read.</li>'); };
m.src = url;
} else { done(); }
});
bAnalyze.addEventListener('click', function () {
if (!file) return;
bAnalyze.disabled = true; bAnalyze.textContent = 'Analyzing…';
var reader = new FileReader();
reader.onerror = function () { setError('Could not read the file.'); finish(); };
reader.onload = function () {
var buf = reader.result, e = ext(file.name), found = signature(new Uint8Array(buf.slice(0, 512)));
var want = EXPECT[e], ok = want === found || (want === 'text' && found === 'text');
var status = ok ? 'Clear' : 'Mismatch';
function out(hash) {
show(results, '<h3>Analysis <span class="badge ' + (ok ? 'ok' : 'bad') + '">' + (ok ? 'Signature matches' : 'Signature mismatch') + '</span></h3><ul>' +
'<li>Extension: .' + esc(e) + ' (expected: ' + esc(want) + ')</li>' +
'<li>Detected from file header: ' + esc(found) + '</li>' +
'<li>SHA-256: <code style="word-break:break-all">' + esc(hash) + '</code></li></ul>' +
'<p class="note">This is an observation about the file header, not proof of tampering.</p>');
save({ name: file.name, type: kind(file, e), sizeKB: Math.round(file.size / 1024), date: new Date().toISOString().slice(0, 10), status: status });
finish();
}
if (window.crypto && crypto.subtle) {
crypto.subtle.digest('SHA-256', buf).then(function (h) {
out(Array.prototype.map.call(new Uint8Array(h), function (b) { return ('0' + b.toString(16)).slice(-2); }).join(''));
}).catch(function () { out('unavailable in this browser'); });
} else { out('unavailable in this browser'); }
};
reader.readAsArrayBuffer(file);
function finish() { bAnalyze.disabled = false; bAnalyze.textContent = 'Analyze Selected File'; }
});
function save(rec) {
try {
var list = JSON.parse(localStorage.getItem('pixelscan.history') || '[]');
list.push(rec); localStorage.setItem('pixelscan.history', JSON.stringify(list.slice(-50)));
} catch (x) {  }
}
}
initMenu(); initAccordion(); initInspector();
})();